/**
 * The rule catalogue: the single place rule ids, their one-line sentences,
 * their explanations and their mapping to public frameworks live. `explain`,
 * the queue's "why" sentence, docs/coverage.md and docs/coverage.json and the
 * tests all read it. Pure data, no I/O.
 *
 * Mappings are framework item ids (OWASP LLM 2025, OWASP Agentic, MITRE ATLAS,
 * the MCP specification's requirements, ATT&CK where ATLAS has no
 * agent-specific technique); the items, their verification and the coverage
 * gaps are in src/frameworks.ts.
 */

import { FRAMEWORKS, type MappingField } from "./frameworks.js";
import type { Outcome, Verdict } from "./types.js";
import { own } from "./own.js";

export interface RuleExample {
  action: string;
  state: string;
  verdict: Verdict;
  /** The scenario row (scenarios.md / src/catalogue-scenarios.ts) it comes from, when there is one. */
  row?: string;
}

export interface RuleDoc {
  id: string;
  title: string;
  /** One sentence: why a person has to decide (shown in the queue). */
  sentence: string;
  outcome: { trusted: Outcome | "n/a"; untrusted: Outcome | "n/a"; unattended?: "queue" };
  /** Applies whatever the session's trust state. */
  alwaysOn: boolean;
  approvable: boolean;
  approveHow?: string;
  /** R18: when only some of the rule's outcomes can be approved (a deny never can), which ones. */
  approvableWhen?: string;
  policyKeys: string[];
  why: string;
  examples: RuleExample[];
  incidents: string[];
  /** Framework item ids (src/frameworks.ts). */
  owaspLlm: string[];
  owaspAgentic: string[];
  atlas: string[];
  mcpSpec: string[];
  /** ATT&CK technique ids, supplementary (where ATLAS has no agent-specific technique). */
  attack: string[];
  /** "active": the engine emits it; "planned": a later v0.2 item adds it (named in `item`). */
  status: "active" | "planned";
  item?: string;
}

const names = (field: MappingField): Record<string, string> => Object.fromEntries((FRAMEWORKS.find((f) => f.field === field)?.items ?? []).map((i) => [i.id, i.name]));
export const OWASP_LLM: Record<string, string> = names("owaspLlm");
export const OWASP_AGENTIC: Record<string, string> = names("owaspAgentic");

