const APPROVE = "launchsafe-firewall queue approve <id> (once, for that exact action; needs your approval passphrase)";
const ASKED = "answer the prompt in Claude Code, or when no one is there: launchsafe-firewall queue approve <id>";


type Def = Omit<RuleDoc, "id" | "status" | MappingField | "attack"> & { status?: RuleDoc["status"] };

type Mapping = Pick<RuleDoc, MappingField> & { attack: string[] };

