    outcome: { trusted: "approve", untrusted: "deny", unattended: "queue" }, alwaysOn: true, approvable: true, approveHow: `${ASKED} (trusted session only)`,
    policyKeys: ["provenance.carryUntrustedWrites"],
    why: "A downloaded file, a file from outside the workspace, or a file written after the session read outside content may have been written by an outsider.",
