const NO_MAPPING: Mapping = { owaspLlm: [], owaspAgentic: [], atlas: [], attack: [], mcpSpec: [] };

export const RULES: Record<string, RuleDoc> = Object.fromEntries(Object.entries(DEFS).map(([id, d]) => [id, { id, ...d, ...(own(MAPPINGS, id) ?? NO_MAPPING), status: d.status ?? "active" }]));

/** Rule ids that have a mapping entry (a test checks this equals the catalogue). */
export const MAPPED_RULE_IDS: readonly string[] = Object.keys(MAPPINGS);

export function ruleDoc(id: string): RuleDoc | null {
  return own(RULES, id) ?? null;
}

